 freshDensity:{title:'Densidad fresca y rendimiento',category:'fresh',standard:'ASTM C138/C138M · referencia temática NTE INEN 1579',source:'https://wsdot.wa.gov/engineering-standards/all-manuals-and-standards/manuals/materials-manual',fields:[field('tare','Masa del recipiente vacío','kg'),field('full','Masa del recipiente lleno','kg'),field('litres','Volumen calibrado del recipiente','L'),field('mass','Masa total realmente pesada de la amasada','kg'),field('nominal','Volumen nominal de la amasada','m³')]},
